{
  "code": "const rows = field.length;
if (rows === 0) return [];
const cols = field[0].length;
const result: string[] = [];
for (let i = 0; i < rows; i++) {
  const row = field[i];
  const newRow: string[] = [];
  for (let j = 0; j < cols; j++) {
    if (row[j] === ' ') {
      let count = 0;
      for (let di = -1; di <= 1; di++) {
        for (let dj = -1; dj <= 1; dj++) {
          if (di === 0 && dj === 0) continue;
          const ni = i + di;
          const nj = j + dj;
          if (ni >= 0 && ni < rows && nj >= 0 && nj < cols && row[ni][nj] === '*') {
            count++;
          }
        }
      }
      newRow.push(count > 0 ? count.toString() : ' ');
    } else {
      newRow.push(row[j]);
    }
  }
  result.push(newRow.join(''));
}
return result;
"
